// === Tab: mySketch ===
////////////////////////////////////////////////////////////////////////////////////////////////////
// Wittgenstein's rod
// Ported from https://www.desmos.com/calculator/m9lx9kxrth
////////////////////////////////////////////////////////////////////////////////////////////////////
OPC.slider('rodLength',300,100,800)
OPC.slider('diameter',200,100,800)
const step = .025
let angle = 0
let pivotx
let pivoty
let grabFlg = false
////////////////////////////////////////////////////////////////////////////////////////////////////
setup = () => {
  createCanvas(windowWidth, windowHeight)
  strokeWeight(2)
  path = createGraphics(width, height)
  path.strokeWeight(8)
	path.noFill()
  pivotx = width / 2 + 120
  pivoty = height / 2
}
draw = () => {
  clear()
  image(path, 0, 0, width, height)
  noFill()
  ellipse(width / 2, height / 2, diameter)
  cpoint(pivotx, pivoty, lerpColor(color('green'),color('white'),sin(frameCount/10)**2))

	path.beginShape()
  for (i = 0; i < step; i += step / 100) {
    angle += step / 100
    x = cos(angle) * diameter / 2 + width / 2
    y = sin(angle) * diameter / 2 + height / 2
    a = atan2(pivoty - y, pivotx - x)
		pathx = x + cos(a) * rodLength
		pathy = y + sin(a) * rodLength
    line(x, y, pathx, pathy)
    path.vertex(pathx, pathy)
  }
  path.endShape()
  cpoint(pathx, pathy, 'white')
  cpoint(x, y, 'red')
}
////////////////////////////////////////////////////////////////////////////////////////////////////
cpoint = (x, y, colour) => {
  fill(colour)
  ellipse(x, y, 20)
}
parameterChanged = (variableName, value) => {
  path.clear()
}
mousePressed = () => {
  grabFlg = dist((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), pivotx, pivoty) < 10
}
mouseDragged = () => {
  if (grabFlg) {
    pivotx = (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)))
    pivoty = (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))
    path.clear()
  }
}
mouseReleased = () => {
  grabFlg = false
}

